{
  "name": "@fivexer/agent",
  "version": "0.7.0",
  "description": "Host-side daemon that registers any local AI agent CLI as a Fivexer worker: it picks tasks off its queue, runs them, and reports results back",
  "type": "module",
  "license": "MIT",
  "keywords": [
    "fivexer",
    "agent",
    "ai-agent",
    "worker",
    "task-queue",
    "claude-code",
    "opencode",
    "codex",
    "mcp"
  ],
  "homepage": "https://github.com/fivexer/fivexer-platform/tree/main/packages/agent#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/fivexer/fivexer-platform.git",
    "directory": "packages/agent"
  },
  "bugs": "https://github.com/fivexer/fivexer-platform/issues",
  "engines": {
    "node": ">=20.12"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "bin": {
    "fivexer-agent": "./dist/bin.js"
  },
  "files": [
    "dist",
    "CHANGELOG.md"
  ],
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./package.json": "./package.json"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@clack/prompts": "^1.8.1",
    "@modelcontextprotocol/sdk": "^1.29.0",
    "ws": "^8.18.0",
    "@fivexer/sdk": "^0.38.0"
  },
  "devDependencies": {
    "@types/node": "^22.10.0",
    "@types/ws": "^8.5.13",
    "typescript": "^5.6.3"
  },
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "start": "node dist/bin.js"
  }
}
